import { runCheck } from './product-copy/src/domain/engine/pipeline/check.ts'
import { repairForDemotion } from './product-copy/src/domain/advice/repair.ts'
import { findingClassOf, waivabilityOf } from './product-copy/src/domain/waivability.ts'
import { FndCodeMeta } from './product-copy/src/domain/engine/formal/codes.ts'
import type { Exclusion } from './product-copy/src/domain/engine/pipeline/gate.ts'
import { GTWR_CODES } from './product-copy/src/domain/engine/lint/codes.ts'
import { createHash } from 'node:crypto'
import { readFileSync } from 'node:fs'
import { SolverBudgetExceededError } from './product-copy/src/domain/engine/formal/needs-review.ts'

const stamp = '2026-01-01T00:00:00.000Z'
const requirement = (id: string, systemName: string, systemResponse: string, trigger?: string) => ({
  id, patternType: trigger ? 'event-driven' : 'ubiquitous', systemName, systemResponse,
  ...(trigger ? { trigger } : {}), negated: false,
  sentence: trigger ? `When ${trigger}, the ${systemName} shall ${systemResponse}.` : `The ${systemName} shall ${systemResponse}.`,
  priority: 'medium', status: 'draft', createdAt: stamp, updatedAt: stamp,
  derives: [], satisfies: [], verifies: [], refines: [],
})
const doc = (requirements: Record<string, unknown>, antonyms: unknown[] = []) => ({
  requirements, glossary: [], antonyms, waivers: [], terms: [], stateModel: { variables: [] },
})
const pair = () => doc({
  A: requirement('A', 'billing ledger', 'record the settled invoice'),
  B: requirement('B', 'telemetry probe', 'publish the heartbeat'),
})
const mode = process.argv[2]
let result: unknown
try {
  if (mode === 'exclusion-equivalence') {
    const emitted = [...new Set([...readFileSync(new URL('./product-copy/src/domain/engine/lint/gtwr.ts', import.meta.url), 'utf8').matchAll(/code:\s*'(GTWR_[^']+)'/g)].map(m => m[1]!))].sort()
    if (emitted.length !== 24 || emitted.some(code => !(GTWR_CODES as readonly string[]).includes(code) || waivabilityOf(code) !== 'scoped')) throw new Error('producer-domain check failed')
    const domains = { reachable: [...GTWR_CODES], signature: [...GTWR_CODES, 'FND_MISSING_TRIGGER', 'FND_CONTRADICTION', 'GTWR_R99_NOT_A_RULE', 'constructor'] }
    const digests: Record<string, unknown> = {}
    for (const [domain, codes] of Object.entries(domains)) {
      const hash = createHash('sha256'); let state = 42
      const next = () => { state = (Math.imul(state, 1664525) + 1013904223) >>> 0; return state }
      for (let i = 0; i < 20_000; i++) {
        const count = i < codes.length ? 1 : next() % (codes.length + 1)
        const findings = Array.from({ length: count }, (_, n) => ({ code: i < codes.length ? codes[i]! : codes[(next() + n) % codes.length]!, severity: 'error' as const, span: [0, 1] as [number, number], message: 'generated finding' }))
        const exclusion: Exclusion = { id: 'R1', reason: i % 31 === 0 ? 'parse-failure' : 'blocking-surface-check', findings }
        const output = repairForDemotion({ reason: 'excluded-from-formal', requirementIds: i % 43 === 0 ? [] : ['R1'], action: 'rewrite required' }, {
          exclusionsById: i % 37 === 0 ? new Map() : new Map([['R1', exclusion]]), findings: [], docPath: 'requirements.json', ...(i % 2 ? { contentHash: () => `sha256:${'0'.repeat(64)}` } : {}),
        })
        hash.update(JSON.stringify(output) + '\n')
      }
      digests[domain] = { cases: 20_000, seed: 42, sha256: hash.digest('hex') }
    }
    result = { emittedCodes: emitted, allPublishedProducerCodesScoped: true, domains: digests }
  } else if (mode === 'catalog') {
    result = { code: 'FND_OPPOSITION_CANDIDATE', waivable: waivabilityOf('FND_OPPOSITION_CANDIDATE'), description: FndCodeMeta.FND_OPPOSITION_CANDIDATE.description }
  } else if (mode === 'classification') {
    result = ['GTWR', 'GTWR_R99_NOT_A_RULE', 'GTWR_R7_VAGUE', 'FND_CONTRADICTION'].map(code => ({ code, class: findingClassOf(code) ?? null, waivable: waivabilityOf(code) ?? null }))
  } else if (mode === 'semantic') {
    const input = doc({
      R1: requirement('R1', 'door controller', 'open the door', 'the passenger presses the door button'),
      R2: requirement('R2', 'door controller', 'close the doors', 'the passenger presses the door button'),
      R3: requirement('R3', 'door controller', 'sound the chime', 'the passenger presses the door button'),
    }, [{ a: 'open', b: 'close' }])
    const embedder = async (texts: readonly string[]) => texts.map(t => {
      const v = new Float32Array(8); v[t === 'sound the chime' ? 1 : 0] = 1; return v
    })
    const report = await runCheck(input as never, { semantic: { embedder } })
    result = report.findings.filter(f => f.code === 'FND_SIMILAR_SEMANTIC').map(f => ({ code: f.code, ids: f.requirementIds, message: f.message }))
  } else if (mode === 'unknown') {
    const report = await runCheck(pair() as never, { needsReviewCheckGroup: async () => 'unknown' as const })
    result = report.coverage.demotions.filter(d => d.reason === 'inconclusive-group')
  } else if (mode === 'excluded-repair') {
    const exclusion: Exclusion = { id: 'R1', reason: 'blocking-surface-check', findings: [{ code: 'FND_MISSING_TRIGGER', severity: 'error', span: [0, 1], message: 'missing trigger' }] }
    result = repairForDemotion({ reason: 'excluded-from-formal', requirementIds: ['R1'], action: 'rewrite required' }, {
      exclusionsById: new Map([['R1', exclusion]]), findings: [], docPath: 'requirements.json', contentHash: () => `sha256:${'0'.repeat(64)}`,
    })
  } else if (mode === 'repair') {
    result = repairForDemotion({ reason: 'inconclusive-group', requirementIds: ['A', 'B'], action: 'undecided' }, {
      exclusionsById: new Map(), findings: [], docPath: 'requirements.json', timeoutMs: 1000,
    })
  } else if (mode === 'unexpected-error' || mode === 'budget-error') {
    const report = await runCheck(pair() as never, {
      ...(mode === 'budget-error' ? { solverBudgetMs: 60_000 } : {}),
      needsReviewCheckGroup: async () => {
        if (mode === 'budget-error') throw new SolverBudgetExceededError('attack injected budget exhaustion', ['Raise --solver-budget-ms'])
        throw new Error('attack unexpected solver failure')
      },
    })
    result = { returned: report === undefined ? 'undefined' : 'report', verified: report?.verified, demotions: report?.coverage.demotions.map(d => d.reason) }
  } else if (mode === 'antonym-cycle') {
    const input = pair(); input.antonyms = [{ a: 'open', b: 'close' }, { a: 'close', b: 'release' }, { a: 'release', b: 'open' }]
    const report = await runCheck(input as never, {})
    result = { returned: report === undefined ? 'undefined' : 'report', verified: report?.verified }
  } else throw new Error('unknown probe mode')
} catch (error) {
  result = { threw: (error as Error).name, message: (error as Error).message }
}
console.log(JSON.stringify(result))

import { Schema } from 'effect'
import { Waiver } from './src/domain/requirements/document.ts'
import { WaiveOp } from './src/domain/requirements/ops.ts'
import { foldOps } from './src/domain/requirements/mutate.ts'
import { MUTATE_OPTIONS } from './src/app/operations/mutate-options.ts'
import { fixtureDoc, ID, HASH } from './src/testing/waiver-fixture.ts'
import { waiverStanding, inertWaiverDiagnostic, matchesFinding, toEngineDoc } from './src/domain/compat.ts'
import { accountWaivers, waivedBlockingIds } from './src/domain/waiver-accounting.ts'
const id=process.argv[2],doc=fixtureDoc('base.json'), code='GTWR_R5_INDEFINITE_ARTICLE', a=ID['LOG-R1'],b=ID['LOG-R2'];
const w={code,reason:'Reviewed legacy wording',requirementIds:[a],contentHash:HASH['LOG-R1']};
const fold=(op:unknown)=>{const r=foldOps(doc,[op as never],'2026-10-05T00:00:00.000Z',MUTATE_OPTIONS);return {write:r.write,waivers:r.document.waivers,failures:r.results.filter(x=>!x.ok)}};
const decode=(schema:any,value:unknown)=>{try{return {accepted:true,value:Schema.decodeUnknownSync(schema)(value)}}catch{return {accepted:false}}};
let input:unknown,result:unknown;
switch(id){
case 'D01':case 'D02': input={...w,code:'FND_CONTRADICTION'};result=waiverStanding(doc,input as never);break;
case 'D03':input={code,reason:w.reason,requirementIds:[a]};result=waiverStanding(doc,input as never);break;
case 'D23':case 'D04':input={...w,contentHash:'sha256:'+'0'.repeat(64)};result=waiverStanding(doc,input as never);break;
case 'D05':input={...w,code:' gtwr_r5_indefinite_article '};result={standing:waiverStanding(doc,input as never),forwarded:toEngineDoc({...doc,waivers:[input as never]}).waivers,write:fold({op:'waive',code:' gtwr_r5_indefinite_article ',reason:w.reason,refs:[a]})};break;
case 'D06': {input={code,reason:w.reason};const standing=waiverStanding(doc,input as never);if(standing.kind!=='inert')throw Error('fixture');result=inertWaiverDiagnostic(doc,input as never,standing,[{code,requirementIds:[a]}]).ops;break;}
case 'D07':input={code,ids:[a,b],findings:[{code,requirementIds:[a]}]};result=matchesFinding(code,[a,b],[{code,requirementIds:[a]}]);break;
case 'D08':input={op:'waive',code:'FND_CONTRADICTION',refs:[a],reason:w.reason};result=fold(input);break;
case 'D09':input={op:'waive',code,reason:w.reason};result=fold(input);break;
case 'D10':input={op:'waive',code,refs:[a],reason:w.reason};result=fold(input);break;
case 'D24':case 'D11':input={op:'waive',code,refs:[a],contentHash:'sha256:'+'0'.repeat(64),reason:w.reason};result=fold(input);break;
case 'D12':input={op:'waive',code:' '+code+' ',refs:[a],reason:w.reason};result=fold(input);break;
case 'D13':input={op:'waive',code,ref:a,reason:w.reason};result=fold(input);break;
case 'D14':input={...w,contentHash:'prefix-'+w.contentHash+'-suffix'};result=decode(Waiver,input);break;
case 'D15':input={...w,requirementIds:[]};result=decode(Waiver,input);break;
case 'D16':input={...w,reason:''};result=decode(Waiver,input);break;
case 'D17':case 'D18':input={op:'waive',code,refs:[a],contentHash:w.contentHash,reason:w.reason};result=decode(WaiveOp,input);break;
case 'D19':input={waivers:[w],preWaiver:[{code,requirementIds:[a]}]};result=accountWaivers({...doc,waivers:[w]},[{code,requirementIds:[a]}],[],[]);break;
case 'D20':input={fixture:'cases/blocking-lint-one.stored.json'};result=waivedBlockingIds(toEngineDoc(fixtureDoc(input.fixture)));break;
case 'D21':input={...w,contentHash:'sha256:'+'0'.repeat(64)};result=accountWaivers({...doc,waivers:[input]},[],[],[]);break;
case 'D22':input={waiver:w,preWaiver:[],others:[]};result=accountWaivers({...doc,waivers:[w]},[],[],[]);break;
case 'RAW_UNWAIVE': {const raw={...w,code:' GTWR_R5_INDEFINITE_ARTICLE '};const rawDoc={...doc,waivers:[raw]};const st=waiverStanding(rawDoc,raw);if(st.kind!=='inert')throw Error('not inert');const ops=inertWaiverDiagnostic(rawDoc,raw,st,[]).ops!;input={waiver:raw,repairOps:ops};const folded=foldOps(rawDoc,ops as never,'2026-10-05T00:00:00.000Z',MUTATE_OPTIONS);result={write:folded.write,waivers:folded.document.waivers,results:folded.results};break;}
default:throw Error('unknown '+id)
}
console.log(JSON.stringify({id,input,result}));
